let loiStudio=null,loiStudioTimings=[];
const LOI_STUDIO_AUTOSAVE_MS=2500,LOI_STUDIO_TYPE_FACT='Letter type: ',LOI_STUDIO_CONNECTION_FACT='Evidence connection';
const LOI_STUDIO_RANK_CONFIRMATIONS=['firstChoice','rankVoluntary','rankUnpressured','rankNoReciprocity'];
const LOI_STUDIO_RANK_SENTENCE='After completing my interviews, I am writing to let you know that I intend to rank your program first on my rank order list.';
function loiStudioFirstChoiceConfirmed(fields){return LOI_STUDIO_RANK_CONFIRMATIONS.every(k=>fields[k]===true);}
function loiStudioGuidance(fold=false){if(fold)return `<details class="studioNote studioGuidanceFold"><summary>NRMP communication guidance</summary>${loiStudioGuidance(false).replace(/^<div class="studioNote"><h3>NRMP communication guidance<\/h3>/,'<div class="studioGuidanceBody">')}</details>`;return `<div class="studioNote"><h3>NRMP communication guidance</h3><p><b>Match agreement requirements:</b> You may keep your ranking intentions private. Programs must not solicit ranking commitments or ask for your ranking preferences. Applicants must not seek reciprocal ranking commitments. Voluntary expressions of interest are permitted; voluntary ranking disclosure is not automatically a Match violation.</p><p><b>Professional guidance:</b> Follow program-specific restrictions on post-interview communication. Keep correspondence professional, limited, and genuinely relevant; do not use it to ascertain the program's ranking intentions. NRMP's Code of Conduct also carries professional obligations.</p><p class="tiny">Sources: <a href="https://www.nrmp.org/wp-content/uploads/2026/09/2027-MPA-Main-Match-Applicant.pdf" target="_blank" rel="noopener noreferrer">2027 applicant agreement §§6.3–6.5</a> · <a href="https://www.nrmp.org/wp-content/uploads/2026/04/2027-MPA-Main-Match-Programs.pdf" target="_blank" rel="noopener noreferrer">2027 program agreement §§6.4–6.5</a> · <a href="https://www.nrmp.org/wp-content/uploads/2023/08/NRMP-Match-Codes-of-Conduct_Applicants.pdf" target="_blank" rel="noopener noreferrer">Applicant Code of Conduct</a>. Verified October 20, 2026.</p></div>`;}
// Remove only the sentence inserted by this composer, never rebuild student edits on a consent change.
function loiStudioSetField(st,key,value){
 st.fields[key]=value;
 if(st.templateId==='intent'&&st.rankGenerated&&!loiStudioFirstChoiceConfirmed(st.fields)){
  const prior=st.text;
  if(typeof prior==='string')st.text=prior.replace(prior.includes(' '+LOI_STUDIO_RANK_SENTENCE)?' '+LOI_STUDIO_RANK_SENTENCE:LOI_STUDIO_RANK_SENTENCE,'');
  st.rankGenerated=false;loiStudioForget(['studio-text']);const ta=document.getElementById('studio-text');if(ta&&typeof st.text==='string')ta.value=st.text;
  notice(prior!==st.text?'Optional first-choice sentence removed. Your other edits are preserved.':'Confirmation withdrawn. Your edited words are preserved; review any ranking language you wrote yourself.');
 }
 if(!st.edited)st.text=null;
}
// Mirrors the WordPress gateway entitlement (student tier 360 / IV Prep Complete) and the admin Student View preview. Templates are fictional public content; private saving stays behind the server LOI capability.
function lettersStudioEnabled(){return studentPreview()||actor?.role==='student'&&['360','ivprep_complete'].includes(actor?.tier);}
function clearLettersStudioMemory(){if(loiStudio?.autosaveTimer)clearTimeout(loiStudio.autosaveTimer);loiStudio=null;}
function loiStudioForget(ids){if(typeof forgetDrafts==='function')forgetDrafts(ids);}
function loiStudioRecordTiming(label,t0){loiStudioTimings.push({label,ms:Math.round((typeof performance!=='undefined'?performance.now():Date.now())-t0),at:new Date().toISOString()});if(loiStudioTimings.length>60)loiStudioTimings.shift();}
const loiStudioNow=()=>typeof performance!=='undefined'?performance.now():Date.now();
function loiStudioProgramPhrase(f){const prog=loiStudioValue(f,'programName'),spec=loiStudioValue(f,'specialty');return prog.toLowerCase().includes(spec.toLowerCase())?prog:`${prog} in ${spec}`;}
function loiStudioState(){if(!loiStudio)loiStudio={mode:'gallery',templateId:null,fields:{},text:null,edited:false,pick:'',bind:null,epoch:null,save:{status:'unbound',message:'',at:null,digest:null},saving:false,pendingSave:false,autosaveTimer:null,evidence:{status:'idle',key:null,facts:[],coverage:null,program:null,error:''},picks:{}};return loiStudio;}
function loiStudioTemplate(id){return LOI_STUDIO_TEMPLATES.find(t=>t.id===id)||null;}
const loiStudioClean=v=>String(v??'').replace(/\r\n?/g,'\n').replace(/[ \t]+\n/g,'\n').trim();
function loiStudioValue(fields,key){const spec=LOI_STUDIO_FIELDS[key];if(spec.type==='checkbox')return fields[key]===true;const v=loiStudioClean(fields[key]);return v||spec.ph;}
function loiStudioLines(fields,key,max=3){const v=loiStudioClean(fields[key]);if(!v)return [LOI_STUDIO_FIELDS[key].ph];return v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,max);}
function loiStudioSalutation(fields){const pd=loiStudioClean(fields.pdName);return 'Dear '+(pd?(/^dr\.?\s/i.test(pd)?pd:'Dr. '+pd):'Program Director')+',';}
function loiStudioSignature(fields){const lines=['Sincerely,',loiStudioValue(fields,'yourName')];const extra=[loiStudioClean(fields.aamcId)?'AAMC ID '+loiStudioClean(fields.aamcId):'',loiStudioClean(fields.contact)].filter(Boolean);if(extra.length)lines.push(extra.join(' · '));return lines.join('\n');}
function loiStudioReasonsParagraph(fields,key='reasons'){const lines=loiStudioLines(fields,key);if(lines.length===1)return lines[0];const lead=['First, ','Second, ','Third, '];return lines.map((l,k)=>lead[k]+l.charAt(0).toLowerCase()+l.slice(1)).join(' ');}
// ---- RISE evidence (read-only, SUPPORTED facts only; never a research request) ----
const loiStudioStrings=x=>typeof x==='string'?[x]:Array.isArray(x)?x.flatMap(loiStudioStrings):x&&typeof x==='object'?Object.values(x).flatMap(loiStudioStrings):[];
function loiStudioFieldLabel(field){return String(field||'').replace(/^research\./,'').replaceAll('_',' ').replace(/\.\w+/g,m=>' '+m.slice(1)).trim();}
function loiStudioFactText(fact){const parts=loiStudioStrings(fact?.value).map(s=>s.trim()).filter(s=>s.length>=8);let t=parts.join('; ').replace(/\s+/g,' ').trim();if(t.length>320)t=t.slice(0,317).replace(/\s+\S*$/,'')+'…';return t;}
function loiStudioFactSentence(fact){const t=loiStudioFactText(fact);if(!t)return '';const s=t.charAt(0).toUpperCase()+t.slice(1);return /[.!?…]$/.test(s)?s:s+'.';}
