function loiStudioSubject(){const st=loiStudioState();return composeLoiStudio(st.templateId,st.fields)?.subject||'';}
function loiStudioProgramOptions(){if(studentPreview()||typeof myInterviews!=='function')return [];const seen=new Set(),out=[];for(const i of myInterviews()){const name=(i.programName||(i.program&&typeof P==='function'?P(i.program).name:'')||'').replace('Fictional ','').trim();if(!name||seen.has(name))continue;seen.add(name);out.push({id:i.id,name,specialty:i.intake?.specialty||(i.program&&typeof P==='function'?P(i.program).specialty:'')||'',verified:Boolean(i.program),saveable:Boolean(i.program)&&typeof loiEnabled==='function'&&loiEnabled()});}return out;}
