async function loiStudioFlush(){const st=loiStudioState();if(!loiStudioBound(st)||!loiStudioDirty(st))return true;clearTimeout(st.autosaveTimer);st.autosaveTimer=null;try{await loiStudioSave({auto:false});return st.save.status==='saved';}catch{return false;}}
