function loiStudioSaveStatusText(st){const bound=loiStudioBound(st);if(studentPreview())return ['preview','PREVIEW · NOT SAVED','Administrator preview: nothing is saved. Students see their own saving controls here.'];if(!bound){if(loiStudioSavingAvailable())return ['unbound','NOT SAVED TO YOUR ACCOUNT','Pick one of your saved interviews above to save this letter to your account. Until then it lives in this tab only; copy or download it before you leave.'];return ['unbound','NOT SAVED TO YOUR ACCOUNT','Saving letters to your account is not available for this workspace yet. Your letter lives in this tab only; copy or download it before you leave.'];}const s=st.save;const when=s.at?new Date(s.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'';if(s.status==='saving')return ['saving','SAVING…','Saving to your account.'];if(s.status==='saved')return ['saved','SAVED TO YOUR ACCOUNT',`Saved${when?' at '+when:''} · ${esc(typeof title==='function'?title(bound):bound.programName||'')}. Reopen it any time from Letters of Interest.`];if(s.status==='conflict')return ['conflict','NEEDS YOUR REVIEW',esc(s.message)];if(s.status==='error')return ['error','SAVE FAILED · TEXT KEPT',esc(s.message)];return ['unsaved','UNSAVED CHANGES','Autosaves a moment after you stop typing, or save now.'];}
